import{_ as i,o as a,c as t,ae as n}from"./chunks/framework.Bwt6MOeu.js";const u=JSON.parse('{"title":"Boundary-Centric Cyber Hypergraph","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boundary-centric-cyber-hypergraph.md","filePath":"guide/boundary-centric-cyber-hypergraph.md"}'),r={name:"guide/boundary-centric-cyber-hypergraph.md"};function l(o,e,s,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="boundary-centric-cyber-hypergraph" tabindex="-1">Boundary-Centric Cyber Hypergraph <a class="header-anchor" href="#boundary-centric-cyber-hypergraph" aria-label="Permalink to &quot;Boundary-Centric Cyber Hypergraph&quot;">​</a></h1><p>This page is the public manual entry point for the boundary-first evidence model inside SocioProphet.</p><p>The Boundary-Centric Cyber Hypergraph explains how the system models crossings, contracts, evidence, expectations, findings, and artifacts without collapsing the platform into a vague stream of unrelated events.</p><p>At any point, the boundary is the unit of truth.</p><h2 id="_1-core-purpose" tabindex="-1">1. Core purpose <a class="header-anchor" href="#_1-core-purpose" aria-label="Permalink to &quot;1. Core purpose&quot;">​</a></h2><p>This model exists to make cross-boundary behavior explainable, attributable, and auditable.</p><p>It gives the platform a stable way to describe:</p><ul><li>what crossed a boundary</li><li>under what contract</li><li>with what evidence</li><li>with what missing evidence</li><li>with what finding or contradiction</li><li>with what attached artifact or state object</li></ul><p>This is useful for analytics, operator workflows, forensics, policy, and institutional review.</p><h2 id="_2-core-chain" tabindex="-1">2. Core chain <a class="header-anchor" href="#_2-core-chain" aria-label="Permalink to &quot;2. Core chain&quot;">​</a></h2><p>The core chain is:</p><p><strong>Component → Port → Contract → BoundaryEvent</strong></p><p>This is the public-safe structural spine.</p><h3 id="component" tabindex="-1">Component <a class="header-anchor" href="#component" aria-label="Permalink to &quot;Component&quot;">​</a></h3><p>A component is a system participant such as:</p><ul><li>device</li><li>operating system</li><li>application</li><li>browser profile</li><li>service</li><li>session</li><li>storage volume</li><li>control domain</li></ul><h3 id="port" tabindex="-1">Port <a class="header-anchor" href="#port" aria-label="Permalink to &quot;Port&quot;">​</a></h3><p>A port is the attachment point or boundary surface through which a component interacts.</p><p>Publicly, ports may be discussed in terms of surfaces such as:</p><ul><li>network</li><li>identity</li><li>execution</li><li>storage</li><li>user interface</li><li>content</li></ul><h3 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h3><p>A contract defines who may talk, how they may talk, and under what rules.</p><p>It includes ideas such as:</p><ul><li>allowed peers</li><li>allowed actions</li><li>capabilities</li><li>rate limits</li><li>cryptographic requirements</li><li>expected observables</li><li>control-domain constraints</li></ul><h3 id="boundaryevent" tabindex="-1">BoundaryEvent <a class="header-anchor" href="#boundaryevent" aria-label="Permalink to &quot;BoundaryEvent&quot;">​</a></h3><p>A boundary event is the authoritative externalized fact that a crossing or attempted crossing occurred.</p><p>It captures the crossing itself rather than burying the important meaning inside raw interior churn.</p><h2 id="_3-evidence-expectations-and-findings" tabindex="-1">3. Evidence, expectations, and findings <a class="header-anchor" href="#_3-evidence-expectations-and-findings" aria-label="Permalink to &quot;3. Evidence, expectations, and findings&quot;">​</a></h2><p>This model becomes powerful when evidence and absence are both first-class.</p><h3 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h3><p>Evidence can be:</p><ul><li>direct</li><li>corroborating</li><li>contradictory</li><li>absent-expected</li></ul><p>That last category matters.</p><h3 id="expectations" tabindex="-1">Expectations <a class="header-anchor" href="#expectations" aria-label="Permalink to &quot;Expectations&quot;">​</a></h3><p>An expectation encodes what the system expected to observe at a boundary.</p><p>This may include:</p><ul><li>an event that normally follows another</li><li>a required field</li><li>a time window</li><li>a provenance signal</li><li>an integrity record</li></ul><h3 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h3><p>A finding is the materialized result when evidence and expectation are compared.</p><p>Publicly, findings may include things such as:</p><ul><li>missing record</li><li>missing field</li><li>gap</li><li>schema drift</li><li>time skew</li><li>invalid signature</li><li>boundary violation</li></ul><h2 id="_4-negative-evidence-is-first-class" tabindex="-1">4. Negative evidence is first-class <a class="header-anchor" href="#_4-negative-evidence-is-first-class" aria-label="Permalink to &quot;4. Negative evidence is first-class&quot;">​</a></h2><p>One of the strongest public-safe ideas in this model is that absence is not invisible.</p><p>The system can represent:</p><ul><li>an expected observation that did not occur</li><li>a record was expected to exist but was absent</li><li>a contract path that was expected but never materialized</li><li>a provenance chain that broke</li></ul><p>This matters because real systems fail not only by emitting bad signals, but also by failing to emit expected ones.</p><h2 id="_5-artifact-families" tabindex="-1">5. Artifact families <a class="header-anchor" href="#_5-artifact-families" aria-label="Permalink to &quot;5. Artifact families&quot;">​</a></h2><p>Artifacts are first-class.</p><p>Publicly, artifact families include things such as:</p><ul><li>email messages</li><li>font files</li><li>documents</li><li>cookies</li><li>token stores</li><li>browser state</li><li>configuration files</li><li>databases</li><li>binaries or modules</li><li>log streams and log records</li></ul><p>Artifacts attach to boundary events when they cross a port or become relevant to a finding.</p><h2 id="_6-log-integrity" tabindex="-1">6. Log integrity <a class="header-anchor" href="#_6-log-integrity" aria-label="Permalink to &quot;6. Log integrity&quot;">​</a></h2><p>Log integrity is also first-class.</p><p>The model tracks:</p><ul><li>log streams</li><li>log records</li><li>ingest runs</li><li>integrity signals</li><li>gaps</li><li>sequence issues</li><li>signature validity</li><li>schema drift</li></ul><p>This matters because the evidence model cannot rely on logs while treating the log surface itself as unquestioned.</p><h2 id="_7-why-boundary-first-reasoning-matters" tabindex="-1">7. Why boundary-first reasoning matters <a class="header-anchor" href="#_7-why-boundary-first-reasoning-matters" aria-label="Permalink to &quot;7. Why boundary-first reasoning matters&quot;">​</a></h2><p>Most systems over-focus on internal churn and under-focus on what crossed the boundary.</p><p>Boundary-first reasoning improves:</p><ul><li>explainability</li><li>least privilege</li><li>policy review</li><li>forensics</li><li>audit</li><li>institutional accountability</li><li>negative-evidence handling</li></ul><p>It gives the system a legible place to make a decision.</p><h2 id="_8-relation-to-the-broader-platform" tabindex="-1">8. Relation to the broader platform <a class="header-anchor" href="#_8-relation-to-the-broader-platform" aria-label="Permalink to &quot;8. Relation to the broader platform&quot;">​</a></h2><p>The Boundary-Centric Cyber Hypergraph is not isolated.</p><p>It connects directly to:</p><ul><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="/documentation/guide/authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li></ul><h2 id="_9-public-safe-boundary" tabindex="-1">9. Public-safe boundary <a class="header-anchor" href="#_9-public-safe-boundary" aria-label="Permalink to &quot;9. Public-safe boundary&quot;">​</a></h2><p>This page explains the model and its purpose.</p><p>It does not publish:</p><ul><li>restricted collection logic</li><li>exploit-oriented instrumentation</li><li>sensitive evasion details</li><li>private runbooks</li><li>privileged operational mechanics</li><li>tactical material that materially increases misuse value</li></ul><p>That restriction is part of the platform design.</p><h2 id="_10-why-this-matters" tabindex="-1">10. Why this matters <a class="header-anchor" href="#_10-why-this-matters" aria-label="Permalink to &quot;10. Why this matters&quot;">​</a></h2><p>This model helps unify several things that are often separated badly:</p><ul><li>identity and entity analytics</li><li>operator workflows</li><li>defensive validation</li><li>evidence and provenance</li><li>institutional governance</li><li>public-safe system explanation</li></ul><p>It gives the platform a real boundary-language rather than a pile of disconnected events.</p><h2 id="_11-use-this-page" tabindex="-1">11. Use this page <a class="header-anchor" href="#_11-use-this-page" aria-label="Permalink to &quot;11. Use this page&quot;">​</a></h2><p>Use this page when the question is:</p><ul><li>What is the boundary-first model?</li><li>How do components, ports, contracts, and events fit together?</li><li>How does the system represent missing evidence?</li><li>How does this model connect analytics, governance, and defense into one explainable architecture?</li></ul>',77)])])}const b=i(r,[["render",l]]);export{u as __pageData,b as default};
